from pathlib import Path
import json, html
root=Path(__file__).resolve().parent
film=root/'film'
summary=json.loads((root/'recording-summary.json').read_text())
atlases={n:json.loads((film/'assets'/f'{n}.json').read_text()) for n in ['characters','foreground','map']}
(film/'assets/atlas-data.js').write_text('window.COZY_ATLASES='+json.dumps(atlases,separators=(',',':'))+';\nwindow.COZY_EVENTS='+(root/'source-events.json').read_text()+';\n')
index='''<!doctype html><html lang="en" data-resolution="landscape" data-composition-variables='[{"id":"title","type":"string","label":"Title","default":"A village you can change."}]'><head><meta charset="utf-8"><meta name="viewport" content="width=1920,height=1080"><title>GODMODE · cozy prototype</title><script src="assets/gsap.min.js"></script><script src="assets/recording-data.js"></script><script src="assets/atlas-data.js"></script><script src="assets/render-cozy.js"></script><style>*{margin:0;padding:0;box-sizing:border-box}html,body{width:1920px;height:1080px;overflow:hidden;background:#193d32}#root{position:absolute;inset:0}</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="72" data-width="1920" data-height="1080"><div id="cozy" class="clip" data-composition-id="cozy" data-composition-src="compositions/cozy.html" data-start="0" data-duration="72" data-track-index="1" data-track-kind="graphics" data-width="1920" data-height="1080"></div></div><script>window.__timelines=window.__timelines||{};window.__timelines.main=gsap.timeline({paused:true}).to({},{duration:72});</script></body></html>'''
(film/'index.html').write_text(index)
def caption(id,start,duration,title,sub='',beat=None):
 return f'<div id="{id}" class="clip" data-start="{start}" data-duration="{duration}" data-track-index="4" data-beat="{beat or id}" data-hold="Read the actual recorded state and receipt"><div class="caption"><h1>{title}</h1>{f"<p>{sub}</p>" if sub else ""}</div></div>'
def receipt(id,start,beat,name,explanation):
 e=summary['beats'][beat]['event'];quote=html.escape(str(e['payload']['text']))
 return f'<div id="{id}" class="clip" data-start="{start}" data-duration="5" data-track-index="5" data-hold="Actual dialogue receipt held for reading" data-beat="{id}"><div class="paper"><h2>{name}</h2><blockquote>“{quote}”</blockquote><p>{explanation}</p><small>Actual dialogue · {html.escape(e["id"])} · step {e["step"]}</small></div></div>'
parts=[
caption('opening-caption',0,5,'A village you can change.','Grow a little. Get to know your neighbors.'),
receipt('mara-receipt',5,'mara-response','Mara · careful planner','This grain gift was declined. She goes to inspect.'),
caption('plant-caption',10,5,'Plant one seed.','An actual grain leaves your inventory.'),
caption('water-caption',15,6,'Water. Give it time.','One water · 180 fixed steps to ripen.'),
caption('harvest-caption',21,5,'Four grain, actually harvested.','Your pack: 3 → 7 grain. No invented supplies.'),
receipt('ada-receipt',26,'ada-response','Ada · practical baker','She accepts the grain. Trust +5 · affinity +8.'),
receipt('wren-receipt',31,'wren-response','Wren · sociable courier','They accept the gift and want to spread good news.'),
caption('bid-caption',43,5,'They choose different jobs.','Ada brings food. Mara prepares. Wren invites.'),
caption('work-caption',48,5,'Supplies. Travel. Actual work.','One timber and 30 setup steps prepare the square.'),
caption('festival-caption',53,5,'Watch the village come together.','Preparations finish. The neighbors arrive.'),
caption('comparison-caption',58,9,'Same past. Two recorded futures.','Both continuations replay to their exact state hashes.'),
caption('end-caption',67,5,'Your change becomes a shared memory.','GODMODE · cozy prototype · Meta connection pending.'),
]
rule=summary['beats']['rule-applied']['event']
parts.insert(7,f'<div id="rule-receipt" class="clip" data-start="36" data-duration="7" data-track-index="5" data-hold="Exact field change held for reading" data-beat="exact-editor"><div class="paper rule"><h2>One exact, supported edit</h2><div class="field">organizer</div><div class="change"><s>player</s> → villagers</div><p>Manual field edit. Previewed, validated, then applied.</p><small>Actual rule receipt · {rule["id"]} · revision 1<br>Natural-language parsing is not connected.</small></div></div>')
parts.append(f'<div id="branch-left" class="clip" data-start="58" data-duration="9" data-track-index="5"><div class="branch left"><span>ORIGINAL RULE · player organizes</span><strong id="phase-left">Still planning</strong><small id="outcome-left">0 food delivered · setup incomplete</small></div></div>')
parts.append(f'<div id="branch-right" class="clip" data-start="58" data-duration="9" data-track-index="5"><div class="branch right"><span>MANUAL EDIT · villagers organize</span><strong id="phase-right">Villagers organizing</strong><small id="outcome-right">Recorded continuation of the same past</small></div></div>')
css='''#root{position:absolute;inset:0;overflow:hidden;color:#213c34;font-family:Nunito,sans-serif}canvas{position:absolute;inset:0;width:1920px;height:1080px;image-rendering:pixelated}.disclosure{position:absolute;left:192px;top:108px;background:#fbefd1;padding:12px 22px 14px;border:3px solid #2d4c3d;border-radius:7px;box-shadow:6px 6px 0 #213c34;font-size:28px;font-weight:800;line-height:1.28}.disclosure span{display:block;font-weight:700}.disclosure small{font-size:28px;color:#42513e}.step{position:absolute;right:192px;top:120px;padding:10px 16px;background:#fbefd1;border:2px solid #2d4c3d;border-radius:5px;font-size:28px;font-weight:800}.caption{position:absolute;left:192px;bottom:115px;max-width:1510px}.caption h1{font-family:'EB Garamond',serif;font-size:66px;font-weight:600;line-height:1.04;letter-spacing:-1px;background:#fbefd1;display:table;padding:12px 24px 16px;border:3px solid #2d4c3d;border-radius:4px;box-shadow:7px 7px 0 #213c34}.caption p{font-size:29px;line-height:1.2;font-weight:800;background:#fbefd1;display:table;margin-top:18px;padding:10px 18px;border:2px solid #42513e;border-radius:4px}.paper{position:absolute;left:192px;top:310px;width:740px;background:#fbefd1;border:4px solid #2d4c3d;border-radius:8px;box-shadow:9px 9px 0 #213c34;padding:30px 34px}.paper h2{font-size:29px;color:#5d6847;line-height:1.2;margin:0 0 20px;font-weight:900}.paper blockquote{font-family:'EB Garamond',serif;font-size:44px;font-weight:600;line-height:1.18}.paper p{font-size:28px;line-height:1.26;margin-top:22px;font-weight:800}.paper small{display:block;font:28px/1.3 Nunito,sans-serif;color:#515b43;margin-top:20px}.paper.rule{left:420px;top:315px;width:1080px;padding:35px 45px}.field{font-family:'Space Mono',monospace;font-size:28px;color:#61714c}.change{font-family:'EB Garamond',serif;font-size:66px;font-weight:600;line-height:1.1;margin:12px 0 18px}.change s{color:#7c7155;text-decoration-thickness:3px}.branch{position:absolute;top:285px;background:#fbefd1;border:3px solid #2d4c3d;border-radius:7px;padding:19px 24px;width:690px;box-shadow:6px 6px 0 #213c34}.branch.left{left:192px}.branch.right{right:192px}.branch span{font-size:28px;font-weight:900}.branch strong{display:block;font-family:'EB Garamond',serif;font-size:48px;font-weight:600;line-height:1.1;margin:10px 0}.branch small{font-size:28px;font-weight:800}'''
composition='<template><style>'+css+'</style><div id="root" data-composition-id="cozy" data-width="1920" data-height="1080"><canvas id="cozy-world" class="clip" width="1920" height="1080" data-start="0" data-duration="72" data-track-index="0" data-layout-ignore aria-label="Presentation playback of actual cozy simulation snapshots"></canvas><div id="disclosure" class="clip" data-start="0" data-duration="72" data-track-index="8"><div class="disclosure">Exact rule editor • rule-policy simulation<span>Recorded simulation • edited for time</span><small>Meta disconnected • 0 model calls</small></div></div><div id="step-clock" class="clip" data-start="0" data-duration="72" data-track-index="8"><div class="step" id="sim-step">Recorded step 0 · 0.0s simulated</div></div>'+''.join(parts)+'</div><script>window.createCozyFilm("cozy");</script></template>'
(film/'compositions/cozy.html').write_text(composition)
print('Built72s cozy film with actual event receipts and real branch outcomes.')
